text:
/* 整体背景：用你发的图，加个遮罩让字看得清 */
:root {
--cal-bg-color: #fffaf0;
--cal-bg-image: url('https://i.imgur.com/your-image-url.jpg');
--cal-bg-overlay: rgba(255, 250, 240, 0.7);
/* 字体和强调用色：暖黄透粉的色系 */
--cal-text-color: #5a4a42;
--cal-accent-color: #ffb6b9;
--cal-accent-hover: #fa9c9f;
/* 日历网格 */
--cal-grid-border: 1px solid rgba(255, 182, 185, 0.3);
--cal-cell-bg: transparent;
--cal-cell-hover: rgba(255, 182, 185, 0.15);
/* 今天的高亮 */
--cal-today-bg: rgba(255, 182, 185, 0.25);
--cal-today-text: #d96c75;
/* 圆角和阴影，让整体显得软一点 */
--cal-border-radius: 16px;
--cal-shadow: 0 4px 12px rgba(255, 182, 185, 0.2);
}
/* 给头部加点小装饰，呼应你的小猫 */
.cal-header::after {
content: '🐾';
font-size: 14px;
margin-left: 8px;
opacity: 0.6;
}

